    for _ in range(n-1):
        a,b=map(int,d[cursor:cursor+2]);cursor+=2;graph[a].append(b);graph[b].append(a)
    parent=[0]*n;depth=[0]*n;mask=[0]*n;mask[0]=1<<(ord(labels[0])-97);stack=[0]
    while stack:
        v=stack.pop()
